<script setup lang="ts">
import {ref,onMounted,watch} from 'vue'
const props=defineProps<{api:(path:string,method?:string,data?:unknown,signal?:AbortSignal)=>Promise<any>}>()
const settings=ref({baseUrl:'https://api.xiaomimimo.com/v1',model:'mimo-v2.6-flash',streaming:false,thinking:'mimo-disabled',reuseTtsKey:false,allowLocal:false})
const key=ref(''),configured=ref(false),error=ref(''),saving=ref(false)
watch(()=>settings.value.baseUrl,()=>{key.value='';settings.value.reuseTtsKey=false},{flush:'sync'})
onMounted(async()=>{try{const value=await props.api('/llm');settings.value=value.settings;configured.value=value.configured}catch{error.value='无法读取 AI 配置'}})
function preset(event:Event){if((event.target as HTMLSelectElement).value!=='官方小米 MiMo')return;settings.value={...settings.value,baseUrl:'https://api.xiaomimimo.com/v1',model:'mimo-v2.6-flash',thinking:'mimo-disabled',reuseTtsKey:false}}
async function save(clearKey=false){if(saving.value)return;saving.value=true;error.value='';const secret=key.value;key.value='';try{const value=await props.api('/llm','PUT',{settings:settings.value,key:secret||null,clearKey});settings.value=value.settings;configured.value=value.configured;error.value='配置已保存。更换地址会清除原地址的独立 Key。'}catch(e){error.value=String(e)}finally{saving.value=false}}
</script>
<template><section class="card ai-settings"><h2>AI 创作服务 · {{configured?'Key 已配置':'尚未配置 Key'}}</h2><p>独立于语音生成。仅主动点击 AI 操作发送对应创作文本，在线请求可能收费。</p><form @submit.prevent="save()"><label>服务便捷选项<select @change="preset"><option>自定义 OpenAI-Compatible</option><option>官方小米 MiMo</option></select></label><label>Base URL<input v-model="settings.baseUrl" placeholder="https://api.example.com/v1" required></label><label>LLM 模型<input v-model="settings.model" required maxlength="150"></label><label>Thinking 协议<select v-model="settings.thinking"><option value="omit">不发送（服务默认）</option><option value="mimo-enabled">MiMo thinking enabled</option><option value="mimo-disabled">MiMo thinking disabled</option><option value="enable-thinking">enable_thinking: true</option><option value="disable-thinking">enable_thinking: false</option><option value="effort-low">reasoning_effort: low</option><option value="effort-medium">reasoning_effort: medium</option><option value="effort-high">reasoning_effort: high</option></select></label><label class="check"><input type="checkbox" v-model="settings.streaming">SSE 流式（完整结束后预览）</label><label class="check"><input type="checkbox" v-model="settings.allowLocal">明确允许 HTTP / 私有网络服务：明文传输可能泄漏 Key 和稿件</label><label class="check"><input type="checkbox" v-model="settings.reuseTtsKey" :disabled="settings.baseUrl!=='https://api.xiaomimimo.com/v1'">明确在官方 MiMo 地址复用现有 TTS Key</label><label>独立 LLM Key<input type="password" v-model="key" :disabled="settings.reuseTtsKey" autocomplete="new-password" maxlength="512" placeholder="留空保留同地址现有 Key"></label><button :disabled="saving">保存 AI 设置</button><button type="button" class="quiet" :disabled="saving" @click="save(true)">清除独立 Key</button></form><p role="status">{{error}}</p></section></template>

<style scoped>
.ai-settings{margin-bottom:24px}.ai-settings form{max-width:760px}.ai-settings .check{white-space:normal;align-items:flex-start;line-height:1.7}.ai-settings input[type=checkbox]{flex-shrink:0}.ai-settings button{margin:16px 8px 0 0}
</style>
